const rawTitle = (item.json['Title'] || '').trim();
if (!rawTitle) return { json: { ...item.json, _raw_title_cleaned: '', _title_error: 'Title empty' } };
let cleaned = rawTitle
  .replace(/^[A-Z0-9]{2,}-[A-Z0-9-]+\s+/i, '')
  .replace(/^(Black|White|Grey|Gray|Red|Blue|Green|Yellow|Pink|Purple|Orange|Brown|Silver|Gold|Beige|Khaki|Navy|Cream|Clear|Dark|Light)\s+/i, '')
  .replace(/\s{2,}/g, ' ')
  .trim();
const category = item.json['Category'] || '';
const subcat = item.json['Subcategory'] || '';
const subsubcat = item.json['Sub_subcategory'] || '';
const description = (item.json['Description'] || '').replace(/<[^>]+>/g, ' ').replace(/\s{2,}/g, ' ').trim().substring(0, 500);
return {
  json: {
    ...item.json,
    _raw_title_cleaned: cleaned,
    _category_path: [category, subcat, subsubcat].filter(Boolean).join(' > '),
    _description_preview: description
  }
};

let aiTitle = '';
try {
  aiTitle = (item.json.choices[0].message.content || '').trim().replace(/^"|"$/g, '').replace(/^'|'$/g, '').trim();
} catch (e) { aiTitle = ''; }
if (aiTitle.length > 80) {
  aiTitle = aiTitle.substring(0, 80);
  const lastSpace = aiTitle.lastIndexOf(' ');
  if (lastSpace > 50) aiTitle = aiTitle.substring(0, lastSpace);
}
const fallback = item.json._raw_title_cleaned || item.json['Title'] || '';
const finalTitle = (aiTitle.length > 5) ? aiTitle : fallback.substring(0, 80);
return {
  json: {
    ...item.json,
    _ebay_title: finalTitle,
    _title_length: finalTitle.length,
    _title_source: aiTitle.length > 5 ? 'ai' : 'fallback'
  }
};

const cfg = item.json._config;
const title = item.json._ebay_title || item.json['Title'] || '';
const titleLower = title.toLowerCase();
const prohibitedTerms = ['lock picking', 'locksmith', 'gravity pick', 'lockpick', 'switchblade', 'butterfly knife', 'brass knuckles', 'taser', 'stun gun', 'replica gun'];
if (prohibitedTerms.some(t => titleLower.includes(t))) {
  return { json: { ...item.json, _ebay_price: null, _price_error: 'Prohibited policy item' } };
}
const costRaw = item.json['Cost per item'] || '0';
let cost = parseFloat(String(costRaw).replace(/[^0-9.]/g, '')) || 0;
if (cost === 0) return { json: { ...item.json, _ebay_price: null, _price_error: 'Cost is 0' } };
let rebateApplied = 0;
if (cfg.applyActiveRebate) {
  const rebatePct = parseFloat(item.json['Rebate %'] || '0') || 0;
  const rebateStart = item.json['Rebate Start Date'] || '';
  const rebateEnd = item.json['Rebate End Date'] || '';
  const now = new Date();
  let active = rebatePct > 0;
  if (rebateStart && rebateEnd) {
    active = rebatePct > 0 && now >= new Date(rebateStart) && now <= new Date(rebateEnd);
  }
  if (active) {
    rebateApplied = cost * (rebatePct / 100);
    cost -= rebateApplied;
  }
}
const metroColumns = ['Delivery(ACT)', 'Delivery(NSW_M)', 'Delivery(QLD_M)', 'Delivery(SA_M)', 'Delivery(VIC_M)', 'Delivery(WA_M)'];
let shippingCost = cfg.shippingFallback;
if (!cfg.useFixedShipping) {
  const metros = metroColumns.map(c => parseFloat(String(item.json[c] || '0').replace(/[^0-9.]/g, ''))).filter(v => v > 0);
  if (metros.length > 0) shippingCost = Math.max(...metros);
} else { shippingCost = cfg.estimatedShippingCost; }
let price;
if (cfg.pricingMode === 'flat_markup') {
  const fee = cfg.ebayFeeRate || 0.135;
  const ship = cfg.includeShippingInMarkup ? shippingCost : 0;
  price = (cost + ship + (cfg.flatFee || 2.00)) / (1 - fee);
} else if (cfg.pricingMode === 'target_margin') {
  const target = cfg.targetMarginPct || 0.15;
  const fee = cfg.ebayFeeRate || 0.135;
  price = (cost + shippingCost) / (1 - fee - target);
} else if (cfg.pricingMode === 'percentage') {
  price = cost * cfg.markupMultiplier;
  if (cfg.includeFreeShipping) price += shippingCost;
  if (cfg.applyEbayFeeBuffer) price = price / (1 - cfg.ebayFeeRate);
} else if (cfg.pricingMode === 'flat') {
  price = cost + cfg.flatFee;
  if (cfg.includeFreeShipping) price += shippingCost;
  if (cfg.applyEbayFeeBuffer) price = price / (1 - cfg.ebayFeeRate);
} else {
  price = (cost * cfg.markupMultiplier) + cfg.flatFee;
  if (cfg.includeFreeShipping) price += shippingCost;
  if (cfg.applyEbayFeeBuffer) price = price / (1 - cfg.ebayFeeRate);
}
if (price < cfg.minimumListingPrice) price = cfg.minimumListingPrice;
if (cfg.charmPrice && price > 1) {
  let charm = Math.ceil(price) - 0.01;
  if (charm < price) charm += 1.00;
  price = Math.ceil(charm) - 0.01;
  if (price < cfg.minimumListingPrice) price = cfg.minimumListingPrice;
}
const finalPrice = parseFloat(price.toFixed(2));
const ebayFee = parseFloat((finalPrice * cfg.ebayFeeRate).toFixed(2));
const profit = parseFloat((finalPrice - cost - shippingCost - ebayFee).toFixed(2));
const marginPct = parseFloat(((profit / finalPrice) * 100).toFixed(1));
return {
  json: {
    ...item.json,
    _cost_after_rebate: parseFloat(cost.toFixed(2)),
    _rebate_applied: parseFloat(rebateApplied.toFixed(2)),
    _shipping_baked: parseFloat(shippingCost.toFixed(2)),
    _ebay_fee_est: ebayFee,
    _ebay_price: finalPrice.toFixed(2),
    _profit_estimate: profit,
    _margin_pct: marginPct
  }
};

const cfg = item.json._config;
const imageList = [item.json['Image 1'], item.json['Image 2'], item.json['Image 3'], item.json['Image 4'], item.json['Image 5'], item.json['Image 6']]
  .map(u => (u || '').trim()).filter(u => u.length > 0 && u.startsWith('http'));
if (imageList.length === 0) return { json: { ...item.json, _ebay_images: '', _image_error: 'No images' } };
const cloudName = cfg.cloudinaryCloudName;
const wId = cfg.watermarkPublicId;
const gravity = cfg.watermarkGravity || 'north_west';
const widthScale = (cfg.watermarkWidthPct / 100).toFixed(2);
const xOffset = cfg.watermarkXOffset || 0;
const yOffset = cfg.watermarkYOffset || 0;
const opacity = cfg.watermarkOpacity || 95;
const watermarkLayer = `l_${wId},w_${widthScale},c_scale,g_${gravity},x_${xOffset},y_${yOffset},o_${opacity},fl_relative`;
// Option A: Only Image 1 gets Cloudinary watermark badge; secondary gallery images stay direct CDN URLs
const allImages = imageList.map((url, idx) => idx === 0 ? `https://res.cloudinary.com/${cloudName}/image/fetch/${watermarkLayer}/${url}` : url);
const picURLs = allImages.join('|');
return {
  json: {
    ...item.json,
    _ebay_images: picURLs,
    _primary_watermarked: allImages[0],
    _image_count: allImages.length
  }
};

const title = item.json._ebay_title || item.json['Title'] || '';
const rawDesc = item.json['Description'] || '';
const sku = item.json['SKU'] || '';
const imageList = [item.json['Image 1'], item.json['Image 2'], item.json['Image 3'], item.json['Image 4']]
  .map(u => (u || '').trim()).filter(u => u.length > 0 && u.startsWith('http'));
const heroImage = imageList[0] || '';
const galleryImg1 = imageList[1] || '';
const galleryImg2 = imageList[2] || '';

// Clean tracking pixels while preserving original full HTML description content & structure
let cleanDesc = rawDesc
  .replace(/<img[^>]*dropshipzone[^>]*>/gi, '')
  .replace(/<img[^>]*logo\.png[^>]*>/gi, '')
  .replace(/<h3>\s*Returns,\s*Refunds,?\s*and\s*Replacements[\s\S]*?(?=<h3|<div|$)/gi, '')
  .replace(/<div>\s*<h2>Returns,\s*Refunds,?\s*and\s*Replacements</h2>[\s\S]*?</div>/gi, '')
  .trim();
if (!cleanDesc || cleanDesc.length < 20) {
  cleanDesc = `<p>${rawDesc.replace(/<[^>]+>/g, ' ').replace(/\s{2,}/g, ' ').trim()}</p>`;
}

const mainImageSection = heroImage ? `<div style="background:#FFFFFF;border:1px solid #E5E0D5;border-radius:8px;padding:20px;margin-bottom:24px;text-align:center;"><img src="${heroImage}" alt="${title.replace(/"/g, '&quot;')}" style="max-width:100%;max-height:480px;width:auto;height:auto;border-radius:6px;" /></div>` : '';

let extraGallerySection = '';
if (galleryImg1 && galleryImg2) {
  extraGallerySection = `<div style="display:grid;grid-template-columns:1fr 1fr;gap:20px;margin-bottom:28px;"><div style="background:#FFFFFF;border:1px solid #E5E0D5;border-radius:8px;padding:16px;text-align:center;"><img src="${galleryImg1}" alt="${title.replace(/"/g, '&quot;')}" style="max-width:100%;max-height:380px;width:auto;height:auto;border-radius:6px;" /></div><div style="background:#FFFFFF;border:1px solid #E5E0D5;border-radius:8px;padding:16px;text-align:center;"><img src="${galleryImg2}" alt="${title.replace(/"/g, '&quot;')}" style="max-width:100%;max-height:380px;width:auto;height:auto;border-radius:6px;" /></div></div>`;
} else if (galleryImg1) {
  extraGallerySection = `<div style="background:#FFFFFF;border:1px solid #E5E0D5;border-radius:8px;padding:20px;margin-bottom:28px;text-align:center;"><img src="${galleryImg1}" alt="${title.replace(/"/g, '&quot;')}" style="max-width:100%;max-height:450px;width:auto;height:auto;border-radius:6px;" /></div>`;
}

const html = `<div style="max-width:880px;margin:0 auto;background-color:#F7F5F0;border-radius:12px;padding:28px;box-sizing:border-box;border:1px solid #E2DED4;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,Helvetica,Arial,sans-serif;"><div style="background-color:#F2EFE8;background-image:radial-gradient(#E5E0D5 1px,transparent 1px);background-size:16px 16px;border-radius:10px;padding:42px 20px 36px 20px;text-align:center;margin-bottom:28px;border:1px solid #E5E0D5;position:relative;"><a href="https://www.ebay.com.au/str/pivotliving" target="_blank" style="display:inline-block;padding:6px 20px;background-color:#FAF8F5;border-radius:20px;font-size:11px;font-weight:700;letter-spacing:2px;color:#2C3135;text-transform:uppercase;margin-bottom:14px;border:1px solid #E6D7C3;text-decoration:none;">OFFICIAL EBAY STORE &nbsp;›</a><h1 style="font-size:38px;color:#2C3135;margin:0 0 4px 0;font-weight:600;letter-spacing:-0.5px;"><a href="https://www.ebay.com.au/str/pivotliving" target="_blank" style="color:#2C3135;text-decoration:none;">Piv<span style="position:relative;display:inline-block;">o<span style="position:absolute;left:48%;top:0;bottom:0;width:1.5px;background-color:#2C3135;transform:translateX(-50%);"></span></span>tLiving</a></h1><div style="width:240px;height:1.5px;background-color:#2C3135;margin:0 auto 12px auto;"></div><p style="font-size:14px;color:#4A5056;margin:0;letter-spacing:3px;text-transform:uppercase;font-weight:500;">Modern Lifestyle Goods</p><span style="position:absolute;right:24px;bottom:18px;color:#D8D2C6;font-size:16px;">✦</span></div><div style="display:flex;flex-wrap:wrap;justify-content:space-between;background:#FFFFFF;border:1px solid #E5E0D5;border-radius:8px;padding:14px 22px;margin-bottom:28px;font-size:12px;color:#525B62;letter-spacing:0.5px;text-transform:uppercase;font-weight:600;"><div>100% Australian Stock</div><div style="color:#D2CBC0;">|</div><div>Ships in 24 Hours</div><div style="color:#D2CBC0;">|</div><div>5–10 Business Days</div><div style="color:#D2CBC0;">|</div><div>High Positive Feedback</div></div><div style="background:#FFFFFF;border:1px solid #E5E0D5;border-radius:8px;padding:26px 30px;margin-bottom:28px;"><h2 style="font-size:23px;color:#2C3135;margin:0 0 10px 0;line-height:1.35;font-weight:600;">${title}</h2><div style="font-size:12px;color:#78828A;">Item Code: <span style="color:#2C3135;font-weight:600;">DSZ-${sku}</span> &nbsp;•&nbsp; Condition: <span style="color:#2C3135;font-weight:600;">Brand New In Box</span></div></div>${mainImageSection}<div style="background:#FFFFFF;border:1px solid #E5E0D5;border-radius:8px;padding:32px 34px;margin-bottom:28px;line-height:1.75;color:#383F45;font-size:14px;">${cleanDesc}</div>${extraGallerySection}<div style="background:#FFFFFF;border:1px solid #E5E0D5;border-radius:8px;padding:30px 34px;margin-bottom:28px;"><h3 style="font-size:13px;color:#78828A;margin:0 0 18px 0;font-weight:600;text-transform:uppercase;letter-spacing:1px;">Store Commitment & Customer Care</h3><div style="margin-bottom:22px;"><h4 style="font-size:14px;color:#2C3135;margin:0 0 6px 0;font-weight:600;">100% Australian Stock — Ships in 24 Hours</h4><p style="font-size:13px;line-height:1.6;color:#525B62;margin:0;">All items are held locally in domestic Australian fulfillment centers and dispatched within 24 hours of payment clearance (Monday to Friday). Estimated delivery timeframe is <strong>5 to 10 business days</strong> nationwide, with online tracking provided immediately upon dispatch.</p></div><div style="margin-bottom:22px;"><h4 style="font-size:14px;color:#2C3135;margin:0 0 6px 0;font-weight:600;">High Positive Feedback & Quality Goods</h4><p style="font-size:13px;line-height:1.6;color:#525B62;margin:0;">At <strong>PivotLiving</strong>, we maintain a strong track record of high customer feedback by carefully selecting only reliable, high-grade products. We listen closely to buyer feedback, ensuring every item delivered to your door meets high standards of quality and dependability.</p></div><div><h4 style="font-size:14px;color:#2C3135;margin:0 0 6px 0;font-weight:600;">Dedicated Customer Service</h4><p style="font-size:13px;line-height:1.6;color:#525B62;margin:0;">We are committed to providing helpful, attentive service before and after your purchase. Have a question about this item or your order? Reach out anytime via eBay Messages and our local support team will promptly assist you.</p></div></div><div style="text-align:center;padding:18px 10px 5px 10px;font-size:12px;color:#8A949E;"><p style="margin:0 0 6px 0;font-size:14px;color:#2C3135;font-weight:600;letter-spacing:1px;text-transform:uppercase;"><a href="https://www.ebay.com.au/str/pivotliving" target="_blank" style="color:#2C3135;text-decoration:none;">PivotLiving Store</a></p><p style="margin:0 0 10px 0;">Modern Lifestyle Goods &nbsp;•&nbsp; Official eBay Australia Store</p><a href="https://www.ebay.com.au/str/pivotliving" target="_blank" style="display:inline-block;padding:8px 22px;background-color:#2C3135;color:#F7F5F0;font-size:11px;font-weight:600;text-transform:uppercase;letter-spacing:1.5px;border-radius:4px;text-decoration:none;">Visit Our eBay Store</a></div></div>`;
return { json: { ...item.json, _ebay_description_html: html } };
